    settings = {}
    required_keys = {"endpoint", "enabled"}

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        if '=' not in line:
            raise ValueError("Malformed line: missing '='")

        try:
            key_part, value_part = line.split('=', 1)
            key = key_part.strip()
            value = value_part.strip()
        except ValueError:
            # Should not happen if '=' is checked, but for robustness
            raise ValueError("Malformed line: invalid structure")

        if key in settings:
            raise ValueError(f"Duplicate key found: {key}")

        settings[key] = value

    # Check for missing keys
    missing_keys = required_keys - settings.keys()
    if missing_keys:
        raise ValueError(f"Missing required keys: {', '.join(missing_keys)}")

    # Type conversion for 'enabled'
    if 'enabled' not in settings:
        # Already checked, but defensive programming
        raise ValueError("Missing required key: enabled")

    enabled_str = settings['enabled'].lower()
    if enabled_str == 'true':
        settings['enabled'] = True
    elif enabled_str == 'false':
        settings['enabled'] = False
    else:
        raise ValueError(f"Invalid boolean value for 'enabled': {settings['enabled']}")


    # Check for unknown keys
    for key in settings:
        if key not in required_keys:
            raise ValueError(f"Unknown key found: {key}")

    return settings
